blocks.code:
/* aturan umum (semua layar) */
body { font-size: 16px; }

/* mobile: lebar layar <= 600px */
@media (max-width: 600px) {
    body { font-size: 14px; }
    .container { width: 100%; }
}

/* tablet: 601px s.d. 1024px */
@media (min-width: 601px) and (max-width: 1024px) {
    .container { width: 90%; }
}

materi.code:
/* 1. Aturan umum (desktop) */
.container { width: 80%; margin: 0 auto; }
.kolom { display: flex; gap: 1rem; }

/* 2. Tablet */
@media (min-width: 601px) and (max-width: 1024px) {
  .container { width: 90%; }
}

/* 3. Mobile: kolom ditumpuk */
@media (max-width: 600px) {
  .container { width: 100%; padding: 0 16px; }
  .kolom { flex-direction: column; }
  nav ul { display: none; } /* diganti tombol menu */
}
